#' Paired Binary Test Comparison
#'
#' 
#' @param data .
#' @param gold .
#' @param test1 .
#' @param test2 .
#' @param test3 .
#' @param goldPositive .
#' @param goldNegative .
#' @param test1Positive .
#' @param test1Negative .
#' @param test2Positive .
#' @param test2Negative .
#' @param test3Positive .
#' @param test3Negative .
#' @param referenceType .
#' @param excludeIndeterminate .
#' @param statComp .
#' @param mcnemarMethod .
#' @param ci .
#' @param confLevel .
#' @param showPairCounts .
#' @param showCases .
#' @param plot .
#' @param showConsole .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$summary} \tab \tab \tab \tab \tab a text \cr
#'   \code{results$cohort} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mapping} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$counts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$estimates} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$comparisons} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$discordance} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cases} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$proportionPlot} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$console} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$cohort$asDF}
#'
#' \code{as.data.frame(results$cohort)}
#'
#' @export
pydecisioncompare <- function(
    data,
    gold = NULL,
    test1 = NULL,
    test2 = NULL,
    test3 = NULL,
    goldPositive,
    goldNegative,
    test1Positive,
    test1Negative,
    test2Positive,
    test2Negative,
    test3Positive,
    test3Negative,
    referenceType = "legacy",
    excludeIndeterminate = FALSE,
    statComp = FALSE,
    mcnemarMethod = "midp",
    ci = FALSE,
    confLevel = 0.95,
    showPairCounts = FALSE,
    showCases = FALSE,
    plot = FALSE,
    showConsole = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("pydecisioncompare requires jmvcore to be installed (restart may be required)")

    if ( ! missing(gold)) gold <- jmvcore::resolveQuo(jmvcore::enquo(gold))
    if ( ! missing(test1)) test1 <- jmvcore::resolveQuo(jmvcore::enquo(test1))
    if ( ! missing(test2)) test2 <- jmvcore::resolveQuo(jmvcore::enquo(test2))
    if ( ! missing(test3)) test3 <- jmvcore::resolveQuo(jmvcore::enquo(test3))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(gold), gold, NULL),
            `if`( ! missing(test1), test1, NULL),
            `if`( ! missing(test2), test2, NULL),
            `if`( ! missing(test3), test3, NULL))

    for (v in gold) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in test1) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in test2) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])
    for (v in test3) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- pydecisioncompareOptions$new(
        gold = gold,
        test1 = test1,
        test2 = test2,
        test3 = test3,
        goldPositive = goldPositive,
        goldNegative = goldNegative,
        test1Positive = test1Positive,
        test1Negative = test1Negative,
        test2Positive = test2Positive,
        test2Negative = test2Negative,
        test3Positive = test3Positive,
        test3Negative = test3Negative,
        referenceType = referenceType,
        excludeIndeterminate = excludeIndeterminate,
        statComp = statComp,
        mcnemarMethod = mcnemarMethod,
        ci = ci,
        confLevel = confLevel,
        showPairCounts = showPairCounts,
        showCases = showCases,
        plot = plot,
        showConsole = showConsole)

    analysis <- pydecisioncompareClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

